(function () {
window.__sa = true;
var d = document, root = d.documentElement;
var header = d.querySelector('.site-header');
function headerH() { return header ? header.offsetHeight : 72; }
function setPad() { root.style.scrollPaddingTop = (headerH() + 12) + 'px'; }
setPad();
window.addEventListener('resize', setPad);
var toggle = d.querySelector('.menu-toggle'), menu = d.getElementById('menu-mobile');
function setMenu(open) {
d.body.classList.toggle('menu-open', open);
if (toggle) {
toggle.setAttribute('aria-expanded', String(open));
toggle.setAttribute('aria-label', open ? 'Fechar menu' : 'Abrir menu');
}
if (menu) menu.style.top = headerH() + 'px';
}
if (toggle) toggle.addEventListener('click', function () { setMenu(!d.body.classList.contains('menu-open')); });
if (menu) menu.addEventListener('click', function (e) { if (e.target.closest('a')) setMenu(false); });
d.addEventListener('keydown', function (e) { if (e.key === 'Escape') setMenu(false); });
window.addEventListener('resize', function () { if (window.innerWidth >= 1100) setMenu(false); });
d.querySelectorAll('[data-back]').forEach(function (a) {
a.addEventListener('click', function (e) {
try {
if (d.referrer && new URL(d.referrer).origin === location.origin && history.length > 1) {
e.preventDefault();
history.back();
}
} catch (err) {}
});
});
var faqBtns = d.querySelectorAll('.faq button');
faqBtns.forEach(function (b) {
b.addEventListener('click', function () {
var wasOpen = b.getAttribute('aria-expanded') === 'true';
faqBtns.forEach(function (o) {
o.setAttribute('aria-expanded', 'false');
d.getElementById(o.getAttribute('aria-controls')).classList.remove('open');
});
if (!wasOpen) {
b.setAttribute('aria-expanded', 'true');
d.getElementById(b.getAttribute('aria-controls')).classList.add('open');
}
});
});
d.querySelectorAll('[data-filters]').forEach(function (group) {
var grid = d.getElementById(group.getAttribute('data-filters'));
var more = d.querySelector('[data-more="' + grid.id + '"]');
function apply(t, updateUrl) {
var btn = group.querySelector('[data-filter="' + t + '"]');
group.querySelectorAll('button').forEach(function (b) { b.setAttribute('aria-pressed', String(b === btn)); });
var first = true;
grid.querySelectorAll('.card').forEach(function (c) {
var on = t === 'todos' || c.getAttribute('data-tema') === t;
c.hidden = !on;
c.classList.toggle('first', on && first);
if (on) first = false;
});
grid.classList.toggle('featured', t === 'todos');
if (more) {
if (t === 'todos') more.hidden = true;
else {
more.hidden = false;
var a = more.querySelector('a');
a.href = btn.getAttribute('data-href');
a.textContent = btn.getAttribute('data-title') + ' →';
}
}
if (updateUrl && group.hasAttribute('data-url')) {
var u = new URL(location.href);
if (t === 'todos') u.searchParams.delete('tema'); else u.searchParams.set('tema', t);
history.replaceState(null, '', u);
}
}
group.addEventListener('click', function (e) {
var b = e.target.closest('button');
if (b) apply(b.getAttribute('data-filter'), true);
});
var q = group.hasAttribute('data-url') ? new URLSearchParams(location.search).get('tema') : null;
apply(q && group.querySelector('[data-filter="' + q + '"]') ? q : 'todos', false);
});
var motion = root.classList.contains('motion');
var navLinks = [].slice.call(d.querySelectorAll('[data-nav]'));
var sections = [].slice.call(d.querySelectorAll('main section[id]'));
var toneEls = [].slice.call(d.querySelectorAll('[data-tone]'));
var tones = { creme: '#FBF7EC', palha: '#F2EEDA' };
var pending = motion ? [].slice.call(d.querySelectorAll('[data-reveal], .lines')) : [];
var thoughts = [];
var lastNav = null, lastTone = null, lastThought = -2;
var themeEls = [].slice.call(d.querySelectorAll('[data-header-theme]'));
function bgOf(el) {
var c = getComputedStyle(el).backgroundColor, m = c && c.match(/rgba?\(([^)]+)\)/);
var p = m ? m[1].split(',').map(parseFloat) : null;
if (!p || (p.length > 3 && p[3] === 0)) {
m = getComputedStyle(d.body).backgroundColor.match(/rgba?\(([^)]+)\)/);
p = m ? m[1].split(',').map(parseFloat) : [251, 247, 236];
}
return 'rgba(' + p[0] + ',' + p[1] + ',' + p[2] + ',.92)';
}
function setHeaderTheme(t, el) {
if (!header) return;
if (t && header.getAttribute('data-theme') !== t) header.setAttribute('data-theme', t);
if (el) header.style.setProperty('--hbg', bgOf(el));
}
function setScrolled() { if (header) header.classList.toggle('is-scrolled', window.scrollY > 4); }
window.addEventListener('scroll', setScrolled, { passive: true });
setScrolled();
function updateHeaderTheme() {
if (!header) return;
var line = header.offsetHeight;
for (var i = 0; i < themeEls.length; i++) {
var r = themeEls[i].getBoundingClientRect();
if (r.top <= line && r.bottom > line) {
setHeaderTheme(themeEls[i].getAttribute('data-header-theme'), themeEls[i]);
break;
}
}
}
window.addEventListener('scroll', function () { requestAnimationFrame(updateHeaderTheme); }, { passive: true });
window.addEventListener('resize', updateHeaderTheme);
window.addEventListener('load', updateHeaderTheme);
updateHeaderTheme();
function at(list, y) {
var hit = null;
for (var i = 0; i < list.length; i++) {
var r = list[i].getBoundingClientRect();
if (r.top <= y && r.bottom > y) hit = list[i];
}
return hit;
}
var floatBtn = d.querySelector('.float-wa');
function update() {
var h = window.innerHeight;
if (floatBtn) {
var on = true, hero = d.getElementById('inicio'), ct = d.getElementById('contato');
if (hero) on = hero.getBoundingClientRect().bottom < 80;
var ft=d.querySelector('.site-footer');[ct,ft].forEach(function(x){if(on&&x){var r=x.getBoundingClientRect();if(r.top<h&&r.bottom>0)on=false;}});
floatBtn.classList.toggle('is-hidden', !on);
floatBtn.tabIndex = on ? 0 : -1;
}
if (navLinks.length && sections.length) {
var s = at(sections,(d.querySelector('.site-header')||{getBoundingClientRect:function(){return{bottom:80}}}).getBoundingClientRect().bottom+1);
var id = s ? (s.id === 'sentindo' ? 'ajuda' : s.id) : null;
if (id !== lastNav) {
lastNav = id;
navLinks.forEach(function (a) {
var on = a.getAttribute('data-nav') === id;
a.classList.toggle('is-active', on);
if (on) a.setAttribute('aria-current', 'location'); else a.removeAttribute('aria-current');
});
}
}
var t = at(toneEls, h * 0.5);
var tone = t ? t.getAttribute('data-tone') : 'creme';
if (tone !== lastTone) { lastTone = tone; d.body.style.backgroundColor = tones[tone] || tones.creme; }
if (pending.length) {
pending = pending.filter(function (el) {
var r = el.getBoundingClientRect();
if (r.top < h * 0.94 && r.bottom > 0) { el.classList.add('in'); return false; }
return true;
});
}
if (thoughts.length) {
var cur = -1;
thoughts.forEach(function (li, i) { if (li.getBoundingClientRect().top + li.offsetHeight / 2 < h * 0.6) cur = i; });
if (cur !== lastThought) {
lastThought = cur;
thoughts.forEach(function (li, i) {
li.classList.toggle('cur', i === cur);
li.classList.toggle('past', i < cur);
});
}
}
}
var queued = false;
function onScroll() {
if (queued) return;
queued = true;
setTimeout(function () { queued = false; update(); }, 60);
}
window.addEventListener('scroll', onScroll, { passive: true });
window.addEventListener('resize', onScroll);
window.addEventListener('load', update);
update();
var maps = [].slice.call(d.querySelectorAll('iframe[data-src]'));
function loadMap(f) { if (f.dataset.src) { f.src = f.dataset.src; f.removeAttribute('data-src'); } }
if (maps.length) {
if ('IntersectionObserver' in window) {
var io = new IntersectionObserver(function (es) {
es.forEach(function (e) { if (e.isIntersecting) { loadMap(e.target); io.unobserve(e.target); } });
}, { rootMargin: '400px 0px' });
maps.forEach(function (f) { io.observe(f); });
} else maps.forEach(loadMap);
}
})();